# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: the Browser widget's value (WebPage: a url) and the link rules that turn a url into
#          one a frame can show (EMBED_RULES, eg a YouTube watch link -> its embed player).
#          A link clicked anywhere in the app opens here (State.browse), Zen-Glance style:
#          floating over the app; Esc closes it, its dock button keeps it as the `web` tab.
#          A link's site is checked first (frameable, GET /frameable in api.py): one that
#          refuses to be framed opens in a real browser tab instead.
# Usage: WebPage(url="https://youtu.be/abc").src -> "https://www.youtube.com/embed/abc"
#        await frameable("https://github.com") -> (False, "x-frame-options: deny")
# ---------------------------------------------------------------------------
from __future__ import annotations

import asyncio
import re
from dataclasses import dataclass
from urllib.parse import urlsplit

from ds.util import http

__all__ = ["CHECK_TIMEOUT_S", "EMBED_RULES", "WebPage", "frame_src", "frame_verdict", "frameable", "normalize"]

# How long a link's check may take before the glance opens anyway (with its hint): the user's
# pick, fast over sure (2026-11-17)
CHECK_TIMEOUT_S = 0.5
# Sites like Wikipedia refuse (403) a request that doesn't name its client: a generic name, no
# personal details
CHECK_HEADERS = {"User-Agent": "delulu-smash-link-check/1.0"}

# Why some pages stay blank: sites send `X-Frame-Options: deny` / CSP `frame-ancestors 'none'`
# (eg github.com) so no other page can frame them, against clickjacking (a hidden frame of a
# logged-in site under a decoy button). The browser enforces it; we don't proxy around it
# (that breaks logins and undoes the site's protection). Open ↗, a rule below, or a site's own
# widget instead.
#
# (pattern, embed url with {id}): links a site only lets a frame show in another form. A link
# no rule matches is framed as it is. Add a site here, nothing else needed.
EMBED_RULES: list[tuple[re.Pattern[str], str]] = [
    (
        re.compile(r"^https?://(?:www\.|m\.)?youtube\.com/watch\?(?:.*&)?v=(?P<id>[\w-]{6,})"),
        "https://www.youtube.com/embed/{id}",
    ),
    (re.compile(r"^https?://youtu\.be/(?P<id>[\w-]{6,})"), "https://www.youtube.com/embed/{id}"),
]


def normalize(url: str) -> str:
    """The url as typed, with https:// added when it has no scheme ('ssbwiki.com' -> 'https://ssbwiki.com')."""
    url = url.strip()
    if url and not re.match(r"^[a-z][a-z0-9+.-]*://", url, re.IGNORECASE):
        return f"https://{url}"
    return url


def frame_src(url: str) -> str:
    """What the frame loads for a url: a rule's embed url, else the url itself."""
    for pattern, embed in EMBED_RULES:
        if match := pattern.match(url):
            return embed.format(id=match["id"])
    return url


def frame_verdict(x_frame_options: str, csp: str) -> tuple[bool, str]:
    """Whether a page with these headers may be shown in our frame, and why. X-Frame-Options
    DENY / SAMEORIGIN refuse; so does a CSP frame-ancestors that doesn't allow every site.
    """
    xfo = x_frame_options.strip().lower()
    if xfo in ("deny", "sameorigin"):
        return False, f"x-frame-options: {xfo}"
    for directive in csp.split(";"):
        name, _, sources = directive.strip().partition(" ")
        if name.lower() == "frame-ancestors" and "*" not in sources.split():
            return False, f"frame-ancestors {sources.strip()}"
    return True, ""


async def frameable(url: str) -> tuple[bool | None, str]:
    """Whether the page at url can be shown in our frame: (True / False / None if unknown,
    why).

    One HEAD request (logged in the debug panel; redirects followed, as the frame would), cut
    off after CHECK_TIMEOUT_S. A link a rule rewrites needs none: its embed is made to be
    framed. Not cached (the Caching Policy): a link clicked twice is checked twice.
    """
    if frame_src(url) != url:
        return True, "embed rule"

    async def check() -> tuple[bool | None, str]:
        async with http.arequest(
            "HEAD",
            url,
            source="browser",
            name="frameable check",
            headers=CHECK_HEADERS,
            follow_redirects=True,
            timeout=CHECK_TIMEOUT_S,
        ) as (resp, call):
            if resp.status_code >= 400:  # eg 405: HEAD not allowed; the frame will tell
                return None, f"HTTP {resp.status_code}"
            ok, why = frame_verdict(
                resp.headers.get("x-frame-options", ""), ", ".join(resp.headers.get_list("content-security-policy"))
            )
            call["frameable"] = ok
            return ok, why

    try:
        return await asyncio.wait_for(check(), CHECK_TIMEOUT_S)
    except Exception as error:  # noqa: BLE001  # a slow or failed check: the glance opens with its hint
        return None, type(error).__name__


@dataclass(frozen=True)
class WebPage:
    """A web page to show in the Browser widget; "" = blank (just the address box)."""

    url: str = ""
    frameable: bool | None = None
    """What the check (frameable) found: True shows it, False shows the 'Open in new tab'
    card instead of a blank frame, None (not checked, or no answer) shows it with the hint."""
    why: str = ""
    """The check's reason when refused, eg 'x-frame-options: deny'."""

    @property
    def src(self) -> str:
        return frame_src(self.url)

    @property
    def host(self) -> str:
        """For the tab and the bar, eg 'www.ssbwiki.com'; 'blank' for no url."""
        return urlsplit(self.url).netloc or self.url or "blank"
